module roman_digit_count(\n    input [31:0] n,\n    output reg [63:0] result\n);\n    always @(*) begin\n        if (n >= 32'd12)\n            result = (64'd49 * n) - 64'd247;\n        else begin\n            case (n)\n                32'd1:  result = 64'd4;\n                32'd2:  result = 64'd10;\n                32'd3:  result = 64'd20;\n                32'd4:  result = 64'd35;\n                32'd5:  result = 64'd56;\n                32'd6:  result = 64'd83;\n                32'd7:  result = 64'd116;\n                32'd8:  result = 64'd155;\n                32'd9:  result = 64'd198;\n                32'd10: result = 64'd244;\n                32'd11: result = 64'd292;\n                default: result = 64'd0;\n            endcase\n        end\n    end\nendmodule